# replace task file with generalized major-color component rectangle reconstruction
program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, deque
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            if len(cells) >= 6:
                y0=min(y for y,x in cells); y1=max(y for y,x in cells)
                x0=min(x for y,x in cells); x1=max(x for y,x in cells)
                if (y1-y0+1)*(x1-x0+1) >= 9:
                    for y in range(y0,y1+1):
                        for x in range(x0,x1+1): out[y][x] = color
    return out
'''
(programs/'task-40f10aa2.py').write_text(program)
